  'cta.title': 'ନିୟନ୍ତ୍ରଣ ନିଜ ହାତକୁ ନେବାକୁ ପ୍ରସ୍ତୁତ?',
  'cta.sub': 'ସୁବିଧା ବଦଳରେ ସ୍ୱାଧୀନତା ବାଛିଥିବା ହଜାର ହଜାର ଟ୍ରେଡରଙ୍କ ସହ ଯୋଗ ଦିଅନ୍ତୁ।',
  'cta.boxTitle': 'ଆପଣଙ୍କ ଷ୍ଟ୍ରାଟେଜି ଆପଣଙ୍କର ରହେ। ଆପଣଙ୍କ ସେବା ଆପଣଙ୍କ ମାଲିକାନାରେ ରହେ। ଇନଫ୍ରାଷ୍ଟ୍ରକଚର ଓପନ୍ ରହେ।',
  'cta.boxDesc': 'ଯଦି ଆପଣଙ୍କ ବ୍ୟବସାୟ ପାଇଁ ପ୍ରୋପ୍ରାଇଟାରୀ ଲାଇସେନ୍ସିଂ କିମ୍ବା ବିଶେଷ ସର୍ତ୍ତ ଆବଶ୍ୟକ, ତେବେ ଆମ Discord କିମ୍ବା GitHub ମାଧ୍ୟମରେ ଯୋଗାଯୋଗ କରନ୍ତୁ।',
