  'road.f2t': 'ପ୍ୟୁର୍ ଟ୍ରେଡିଂ ଟର୍ମିନାଲ୍',
  'road.f2d': 'OpenAlgo କୁ ଉନ୍ନତ ଚାର୍ଟିଂ, ଅର୍ଡର ମ୍ୟାନେଜମେଣ୍ଟ, ମାର୍କେଟ୍ ଡେପ୍ଥ, ଏବଂ ରିଅଲଟାଇମ୍ ଆନାଲିଟିକ୍ସ ଥିବା ଏକ ପୂର୍ଣ୍ଣାଙ୍ଗ ଟ୍ରେଡିଂ ଟର୍ମିନାଲ୍ ରେ ରୂପାନ୍ତରିତ କରନ୍ତୁ, ସବୁକିଛି ଏକ ଏକୀକୃତ ଇଣ୍ଟରଫେସରେ।',
