  'road.f3d': 'ଟ୍ରେଡରମାନଙ୍କ ପାଇଁ ଏକ Flutter ମୋବାଇଲ୍ ଆପ୍ଲିକେସନ୍ ତିଆରି କରନ୍ତୁ ଯାହା ଦ୍ୱାରା ସେମାନେ ନିଜ ମୋବାଇଲ୍ ଡିଭାଇସରୁ ସିଧାସଳଖ ନିଜ ଆଲଗୋରିଦମିକ୍ ଟ୍ରେଡିଂ ଷ୍ଟ୍ରାଟେଜି ମ୍ୟାନେଜ୍, ପୋଜିସନ୍ ମନିଟର, ଏବଂ ଟ୍ରେଡ୍ ନିୟନ୍ତ୍ରଣ କରିପାରିବେ।',
  'road.f4t': 'ଚାର୍ଟ ଆଧାରିତ ଟ୍ରେଡ୍ ମ୍ୟାନେଜମେଣ୍ଟ',
  'road.f4d': 'ସରଳ Target, Stoploss ଏବଂ Trailing Stoploss ଅର୍ଡର ସହ, ପ୍ଲସ୍ ରିସ୍କ-ମ୍ୟାନେଜମେଣ୍ଟ ନିୟନ୍ତ୍ରଣ, ପୋଜିସନ୍ ସାଇଜିଂ ଓ ପୂର୍ଣ୍ଣାଙ୍ଗ ପୋଜିସନ୍ ମ୍ୟାନେଜମେଣ୍ଟ ସହିତ ଚାର୍ଟରୁ ସିଧାସଳଖ ଟ୍ରେଡ୍ ମ୍ୟାନେଜ୍ କରନ୍ତୁ।',
  'road.f5t': 'ବ୍ରାକେଟ୍, କଭର ଅର୍ଡର ଓ MTF/AMO ସପୋର୍ଟ',
  'road.f5d': 'ବ୍ରାକେଟ୍ ଅର୍ଡର, କଭର ଅର୍ଡର ସମେତ ଉନ୍ନତ ଅର୍ଡର ପ୍ରକାର ଆଣୁଛୁ, ଏବଂ Margin Trading Facility (MTF) ଓ After Market Orders (AMO) ପ୍ରୋଡକ୍ଟ ପ୍ରକାରକୁ ସପୋର୍ଟ କରୁଛୁ।',
