  'road.f10d': 'ଲାଇଭ୍ ମାର୍କେଟ୍ ସିମୁଲେସନ୍ ଓ ତତକ୍ଷଣାତ୍ ଫିଡବ୍ୟାକ୍ ସହ ଆଲଗୋ ଟ୍ରେଡିଂ ଷ୍ଟ୍ରାଟେଜିକୁ ଦକ୍ଷତାର ସହ ଟେଷ୍ଟ କରିବାକୁ ସ୍ୟାଣ୍ଡବକ୍ସ ମୋଡ୍ କୁ ପୂର୍ଣ୍ଣ ରିଅଲଟାଇମ୍ କରୁଛୁ।',
