  'road.f13d': 'Open Varsity ମାଧ୍ୟମରେ ମାଗଣା, ଓପନ୍ ସୋର୍ସ ଟ୍ରେଡିଂ ଶିକ୍ଷା - ମାର୍କେଟ୍ ମୌଳିକ, ଟେକ୍ନିକାଲ୍ ଆନାଲିସିସ୍, Python ଓ କ୍ୱାଣ୍ଟ, ଡେରିଭେଟିଭ୍ସ, ଟାକ୍ସେସନ୍, ରିସ୍କ ମ୍ୟାନେଜମେଣ୍ଟ ଓ ଟ୍ରେଡିଂ ସାଇକୋଲୋଜି ଉପରେ ପରିଚାଳିତ କୋର୍ସ, ପ୍ରକୃତ ଭାରତୀୟ-ବଜାର ଡାଟା ଉପରେ ସରଳ ଭାଷାରେ।',
