  'priv.control.i2': 'ଟ୍ରେଡିଂ ଡାଟା ଆପଣଙ୍କ ଇନଷ୍ଟାନ୍ସ ଏବଂ ଆପଣଙ୍କ ବ୍ରୋକର ମଧ୍ୟରେ ସିଧାସଳଖ ଯୋଗାଯୋଗ କରେ',
