  'priv.control.i4': 'କୌଣସି ମଧ୍ୟସ୍ଥି ସର୍ଭର କିମ୍ବା କ୍ଲାଉଡ୍ ସେବା ସାମିଲ ନାହିଁ',
  'priv.trans.title': 'ସ୍ୱଚ୍ଛତା',
