  'priv.trans.i4': 'ପ୍ରୋଜେକ୍ଟରେ ଯୋଗଦାନ କରି ପ୍ରାଇଭେସି ମାନଦଣ୍ଡ ବଜାୟ ରଖିବାରେ ସାହାଯ୍ୟ କରିପାରିବେ',
  'priv.third.title': 'ତୃତୀୟ-ପକ୍ଷ ସେବା',
  'priv.third.intro': 'ଏହି ୱେବସାଇଟ୍ (openalgo.in) ବ୍ୟବହାର କରିପାରେ:',
