  'learn.desc': 'ବଜାର, ଟ୍ରେଡିଂ, ନିବେଶ ଏବଂ କ୍ୱାଣ୍ଟିଟେଟିଭ୍ ଫାଇନାନ୍ସ ପାଇଁ ଏକ ଓପନ୍ ସୋର୍ସ ଶିକ୍ଷଣ ପୋର୍ଟାଲ୍। ବ୍ୟାବହାରିକ, ସୁସଂଗଠିତ ଏବଂ ସାଚ୍ଚୋଟ, ପ୍ରତି ତିନି ମାସରେ ନୂତନ ଉଦାହରଣ ସହ ଅପଡେଟ୍ ହୁଏ, ଏବଂ ବିଜ୍ଞାପନ, ଗେଟକିପିଂ ଓ ହାଇପ୍‌ରୁ ମୁକ୍ତ।',
