  'learn.pathIntro': 'ଓପନ୍ ଭାର୍ସିଟିରେ ଏକ ବଜାର-ମୌଳିକ ପ୍ରବେଶ ବିନ୍ଦୁ, ଏକ Python-ରୁ-କ୍ୱାଣ୍ଟ ପାହାଚ, ଏବଂ ଏକ ସମାନ୍ତରାଳ ନୋ-Python AFL ଟ୍ରାକ୍ ରହିଛି।',
