  'learn.pathQuant': 'ଯେତେବେଳେ ଆପଣ ଚାର୍ଟ ତଳେ ଥିବା ସ୍ତର - ବଜାର ଗଠନ ଏବଂ ଗଣିତ - ଜାଣିବାକୁ ଚାହାଁନ୍ତି, {c} କରନ୍ତୁ।',
  'learn.pathAfl': 'Python ବଦଳରେ ଚାର୍ଟରେ କାମ କରିବାକୁ ପସନ୍ଦ କରନ୍ତି କି? ତାହେଲେ ବଦଳରେ {c} କରନ୍ତୁ - ଏହା ଟ୍ରେଡର ଓ ନିବେଶକଙ୍କ ପାଇଁ ଏକ ସମାନ୍ତରାଳ, ନୋ-Python ଟ୍ରାକ୍ ଯାହା AFL ଭାଷାକୁ ଆରମ୍ଭରୁ ଶିଖାଇଥାଏ, ବ୍ୟାକ୍‌ଟେଷ୍ଟ ହୋଇଥିବା ସିଷ୍ଟମ୍ ଏବଂ ଲାଇଭ୍ ଅଟୋମେସନ୍ ପର୍ଯ୍ୟନ୍ତ।',
