  'skill.h1b': 'ଟ୍ରେଡ୍ ଓ ନିର୍ମାଣ କରିବାକୁ',
  'skill.heroDesc': 'OpenAlgo Skills ଆପଣଙ୍କ AI ସହାୟକରେ ପ୍ରସ୍ତୁତ ଟ୍ରେଡିଂ ଜ୍ଞାନ ଯୋଡ଼ିଥାଏ - ଚାର୍ଟ, ସ୍କାନର୍, କଷ୍ଟମ୍ ଇଣ୍ଡିକେଟର୍, ଏବଂ ପ୍ରକୃତ ବ୍ରୋକରେଜ୍ ଖର୍ଚ୍ଚ ସହ ପୂର୍ଣ୍ଣ ବ୍ୟାକ୍‌ଟେଷ୍ଟ।',
  'skill.heroDesc2': 'କୌଣସି କୋଡିଂ ଅନୁଭବ ଆବଶ୍ୟକ ନାହିଁ। ଆପଣ କ’ଣ ଚାହାଁନ୍ତି ତାହା ସରଳ ଭାଷାରେ ଆପଣଙ୍କ AI କୁ କୁହନ୍ତୁ ଏବଂ ଏହା କାମ କରିଦେବ।',
  'skill.heroInstallNote': 'ଏହାକୁ ଥରେ ଆପଣଙ୍କ ଟର୍ମିନାଲରେ ପେଷ୍ଟ କରନ୍ତୁ। ଆପଣଙ୍କ AI ଟୁଲ୍ ସ୍ୱୟଂଚାଳିତ ଭାବେ ଏହାକୁ ନେଇନେବ।',
