  'skill.whatSub': 'ଏକ skill କୁ ଆପଣଙ୍କ AI ପାଇଁ ଏକ ପ୍ଲଗ୍-ଇନ୍ ଭାବରେ ଭାବନ୍ତୁ। ଏହାକୁ ଥରେ ଇନଷ୍ଟଲ୍ କରନ୍ତୁ ଏବଂ ଆପଣଙ୍କ AI ନୂଆ କ୍ଷମତା ପାଇଯିବ - ଯେପରିକି ଏକ ଇଣ୍ଡିକେଟର୍ ଚାର୍ଟ କରିବା, ଷ୍ଟକ୍ ସ୍କାନ୍ କରିବା, କିମ୍ବା ଏକ ପୂର୍ଣ୍ଣ ବ୍ୟାକ୍‌ଟେଷ୍ଟ ଚଲାଇବା, ସବୁକିଛି ଏକ ନିର୍ଦ୍ଦେଶରେ।',
  'skill.w1t': 'ପ୍ରଥମ ଦିନଠାରୁ ପ୍ରସ୍ତୁତ',
  'skill.w1d': 'କୌଣସି ଲମ୍ବା ପ୍ରମ୍ପ୍ଟ ନାହିଁ, ଟ୍ୟୁଟୋରିଆଲରୁ କୋଡ୍ କପି-ପେଷ୍ଟ କରିବାର ଆବଶ୍ୟକତା ନାହିଁ। କେବଳ ପଚାରନ୍ତୁ, ଆପଣଙ୍କ AI ପୂର୍ବରୁ ଜାଣିଥାଏ।',
  'skill.w2t': 'ପରୀକ୍ଷିତ ରେସିପି',
  'skill.w2d': 'ପ୍ରତ୍ୟେକ skill ବିଶ୍ୱସନୀୟ, ବ୍ୟବହାର ପାଇଁ ପ୍ରସ୍ତୁତ ବିଲ୍ଡିଂ ବ୍ଲକ୍ ସହ ଆସେ - ଅଭିଜ୍ଞ ଟ୍ରେଡରମାନେ ବ୍ୟବହାର କରୁଥିବା ସେହି ସମାନ।',
  'skill.w3t': 'ସରଳ କମାଣ୍ଡ',
  'skill.w3d': '/backtest କିମ୍ବା /indicator-chart ଭଳି ଦ୍ରୁତ ଶର୍ଟକଟ୍ ପ୍ରତ୍ୟେକ କାର୍ଯ୍ୟ ଆରମ୍ଭ କରେ। ବାକି ଆପଣଙ୍କ AI ସମ୍ଭାଳେ।',
  'skill.agentsTitle': 'ଆପଣଙ୍କ AI ଟୁଲ୍ ସହ କାମ କରେ',
  'skill.agentsSub': 'ଆପଣ ଯେକୌଣସି AI କୋଡିଂ ଆପ୍ ବ୍ୟବହାର କରନ୍ତୁ ନା କାହିଁକି, Skills ସିଧାସଳଖ ବସିଯାଏ। ଏକ-ଲାଇନ୍ ଇନଷ୍ଟଲ୍ ସେମାନଙ୍କୁ ରଖିବାର ସଠିକ୍ ସ୍ଥାନ ପାଇଯାଏ।',
