  'skill.packsTitle': 'ଦୁଇଟି Skill ପ୍ୟାକ୍',
  'skill.packsSub': 'ଆପଣଙ୍କୁ ଆବଶ୍ୟକ ଥିବାଟି ବାଛନ୍ତୁ, କିମ୍ବା ଉଭୟ ଇନଷ୍ଟଲ୍ କରନ୍ତୁ। ଉଭୟ ମାଗଣା ଏବଂ ଓପନ୍ ସୋର୍ସ।',
  'skill.tabIndicators': 'ଇଣ୍ଡିକେଟର୍ ଓ ଚାର୍ଟ',
  'skill.tabBacktesting': 'ବ୍ୟାକ୍‌ଟେଷ୍ଟିଂ',
  'skill.indTitle': 'ଇଣ୍ଡିକେଟର୍ ଓ ଚାର୍ଟିଂ Skills',
  'skill.indDesc': 'ଯେକୌଣସି ସିମ୍ବଲ ଉପରେ ଯେକୌଣସି ଇଣ୍ଡିକେଟର୍ ଚାର୍ଟ କରନ୍ତୁ, କଷ୍ଟମ୍ ଇଣ୍ଡିକେଟର୍ ତିଆରି କରନ୍ତୁ, ସେଟଅପ୍ ପାଇଁ ସ୍କାନ୍ କରନ୍ତୁ, ଏବଂ ଲାଇଭ୍ ମୂଲ୍ୟ ଷ୍ଟ୍ରିମ୍ କରନ୍ତୁ - ସବୁକିଛି ଆପଣଙ୍କ AI କୁ ସରଳ ଭାଷାରେ ଅନୁରୋଧ ଦ୍ୱାରା ପରିଚାଳିତ।',
  'skill.askTitle': 'ଆପଣ କ’ଣ ପଚାରିପାରିବେ',
  'skill.ic1t': 'ପ୍ରଥମ ଥର ସେଟଅପ୍',
  'skill.ic1d': 'ଆପଣଙ୍କ ମେସିନରେ ଆପଣଙ୍କ AI ପାଇଁ ଆବଶ୍ୟକ ସବୁକିଛି ଇନଷ୍ଟଲ୍ କରେ। ଏହାକୁ ଥରେ ଚଲାନ୍ତୁ ଏବଂ ଆପଣ ପ୍ରସ୍ତୁତ।',
  'skill.ic2t': 'ଯେକୌଣସି ଇଣ୍ଡିକେଟର୍ ଚାର୍ଟ କରନ୍ତୁ',
  'skill.ic2d': 'ଯେକୌଣସି ଷ୍ଟକ୍ କିମ୍ବା ଇଣ୍ଡେକ୍ସ ଉପରେ EMA, RSI, Supertrend କିମ୍ବା ଅନ୍ୟ ଯେକୌଣସି ଇଣ୍ଡିକେଟର୍ ପାଇଁ ପଚାରନ୍ତୁ। ଆପଣ buy/sell ମାର୍କର୍ ସହ ଏକ ସ୍ୱଚ୍ଛ ଡାର୍କ-ଥିମ୍ ଚାର୍ଟ ପାଆନ୍ତି।',
  'skill.ic3t': 'ନିଜର ଇଣ୍ଡିକେଟର୍ ତିଆରି କରନ୍ତୁ',
  'skill.ic3d': 'ସରଳ ଭାଷାରେ ଏକ ନୂଆ ଇଣ୍ଡିକେଟର୍ ବର୍ଣ୍ଣନା କରନ୍ତୁ। ଆପଣଙ୍କ AI କୋଡ୍ ଲେଖେ, ଏକ ଚାର୍ଟ ଆଙ୍କେ, ଏବଂ ଏହାର ଗତି ଯାଞ୍ଚ କରେ।',
  'skill.ic4t': 'ଏକ ଲାଇଭ୍ ଡାସବୋର୍ଡ ତିଆରି କରନ୍ତୁ',
  'skill.ic4d': 'ଆପଣଙ୍କ ପସନ୍ଦିତ ଇଣ୍ଡିକେଟର୍ ସହ ଏକ ସଠିକ୍ ୱେବ୍ ଡାସବୋର୍ଡ, ମାର୍କେଟ୍‌ରୁ ଲାଇଭ୍ ରିଫ୍ରେସ୍ ହେଉଥିବା।',
  'skill.ic5t': 'ମାର୍କେଟ୍ ସ୍କାନ୍ କରନ୍ତୁ',
  'skill.ic5d': 'ଆପଣଙ୍କ ସର୍ତ୍ତ ସହ ମେଳ ଖାଉଥିବା NIFTY 50 କିମ୍ବା BANKNIFTY ର ଷ୍ଟକ୍ ଖୋଜନ୍ତୁ - RSI ଓଭରସୋଲ୍ଡ, EMA କ୍ରସଓଭର୍, ଭଲ୍ୟୁମ୍ ସ୍ପାଇକ୍, ଏବଂ ଆହୁରି।',
