  'skill.ie4': 'SBIN ପାଇଁ ମଲ୍ଟି-ଟାଇମଫ୍ରେମ୍ ଡାସବୋର୍ଡ',
  'skill.ie5': 'ଓଭରସୋଲ୍ଡ ଷ୍ଟକ୍ ପାଇଁ NIFTY 50 ସ୍କାନ୍ କରନ୍ତୁ',
  'skill.ie6': 'ଇଣ୍ଡିକେଟର୍ ସହ ଲାଇଭ୍ NIFTY ମୂଲ୍ୟ ଷ୍ଟ୍ରିମ୍ କରନ୍ତୁ',
  'skill.btTitle': 'ବ୍ୟାକ୍‌ଟେଷ୍ଟିଂ Skills',
  'skill.btDesc': 'ପ୍ରକୃତ ପୁରୁଣା ଡାଟାରେ ଟ୍ରେଡିଂ ଆଇଡିଆ ଟେଷ୍ଟ କରନ୍ତୁ। ଭାରତୀୟ, US, ଏବଂ କ୍ରିପ୍ଟୋ ମାର୍କେଟ୍ ପାଇଁ ଫି, ଟାକ୍ସ ଏବଂ ସ୍ଲିପେଜ୍ ପୂର୍ବରୁ ଅନ୍ତର୍ଭୁକ୍ତ - ତେଣୁ ଫଳାଫଳ ଆପଣଙ୍କ ଆକାଉଣ୍ଟରେ ପ୍ରକୃତରେ ଦେଖାଯିବା ବିଷୟକୁ ପ୍ରତିଫଳିତ କରେ।',
  'skill.bc1t': 'ପ୍ରଥମ ଥର ସେଟଅପ୍',
  'skill.bc1d': 'ଆପଣଙ୍କ ମେସିନରେ ବ୍ୟାକ୍‌ଟେଷ୍ଟ ଚଲାଇବା ପାଇଁ ଆବଶ୍ୟକ ସବୁକିଛି ପ୍ରସ୍ତୁତ କରେ। ଥରେ ଚଲାନ୍ତୁ।',
  'skill.bc2t': 'ଏକ ଷ୍ଟ୍ରାଟେଜି ବ୍ୟାକ୍‌ଟେଷ୍ଟ କରନ୍ତୁ',
  'skill.bc2d': 'ପ୍ରକୃତ ବ୍ରୋକରେଜ୍ ଓ ଟାକ୍ସ ସହ ପୁରୁଣା ଡାଟାରେ ଯେକୌଣସି ଷ୍ଟ୍ରାଟେଜି ଚଲାନ୍ତୁ। ସରଳ ଭାଷାରେ ଏକ ପୂର୍ଣ୍ଣ ରିପୋର୍ଟ, ପ୍ଲସ୍ ଏକ ପ୍ରୋ-ଗ୍ରେଡ୍ PDF-ଶୈଳୀ ଟିଅରସିଟ୍ ପାଆନ୍ତୁ।',
  'skill.bc3t': 'ସର୍ବୋତ୍ତମ ସେଟିଂସ୍ ଖୋଜନ୍ତୁ',
  'skill.bc3d': 'ଏକ ଷ୍ଟ୍ରାଟେଜିର ସେଟିଂସ୍‌ର ଅନେକ କମ୍ବିନେସନ୍ ଟେଷ୍ଟ କରନ୍ତୁ ଏବଂ ଏକ ଭିଜୁଆଲ୍ ହିଟମ୍ୟାପରେ ସର୍ବୋତ୍ତମଗୁଡ଼ିକୁ ହାଇଲାଇଟ୍ କରନ୍ତୁ।',
  'skill.bc4t': 'ଦ୍ରୁତ ସାନିଟି ଚେକ୍',
  'skill.bc4d': 'ଏକ ଷ୍ଟ୍ରାଟେଜିର ରିଟର୍ନ୍, ଡ୍ରଡାଉନ୍, ଏବଂ ଏହା ଇଣ୍ଡେକ୍ସ ସହ କିପରି ତୁଳନା ହୁଏ ତାହାର ଏକ ଦ୍ରୁତ ପଠନ - କୌଣସି ଫାଇଲ୍ ତିଆରି ହୁଏ ନାହିଁ।',
  'skill.bc5t': 'ଷ୍ଟ୍ରାଟେଜି ତୁଳନା କରନ୍ତୁ',
  'skill.bc5d': 'ସମାନ ଷ୍ଟକ୍ ଉପରେ ଦୁଇ କିମ୍ବା ଅଧିକ ଷ୍ଟ୍ରାଟେଜି ଚଲାନ୍ତୁ ଏବଂ ସେମାନଙ୍କ ଇକ୍ୱିଟି କର୍ଭକୁ ପାଖାପାଖି ରଖନ୍ତୁ।',
  'skill.stratTitle': '12ଟି ପ୍ରସ୍ତୁତ ଷ୍ଟ୍ରାଟେଜି',
  'skill.stratSub': 'ଏକ କାର୍ଯ୍ୟକ୍ଷମ ଷ୍ଟ୍ରାଟେଜି ସହ ଆରମ୍ଭ କରନ୍ତୁ ଏବଂ ଆପଣଙ୍କ ଶୈଳୀ ସହ ମେଳ ଖାଇବାକୁ ଏହାକୁ ସଜାନ୍ତୁ - ଆରମ୍ଭରୁ ତିଆରି କରିବା ଅପେକ୍ଷା ଦ୍ରୁତ।',
