  'gs.hero.badge': 'ନୂତନଙ୍କ ପାଇଁ ଗାଇଡ୍',
  'gs.hero.title2': 'ସହଜରେ ବୁଝାଇଦିଆଯାଇଛି',
  'gs.hero.desc': 'OpenAlgo ପାଇଁ ନୂଆ? ଟେକ୍ନିକାଲ୍ ଲୋକ ନୁହଁନ୍ତି? କୌଣସି ଅସୁବିଧା ନାହିଁ। ଏହି ଗାଇଡ୍ ସବୁକିଛି ଆରମ୍ଭରୁ ବୁଝାଏ - ଏହା କଣ, କାହିଁକି ଏହା ଗୁରୁତ୍ୱପୂର୍ଣ୍ଣ, ଏବଂ କିପରି ଆରମ୍ଭ କରିବେ।',
  'gs.hero.tag1': 'ବୁଝିବା ପାଇଁ କୋଡିଂ ଆବଶ୍ୟକ ନାହିଁ',
  'gs.hero.tag2': 'ପାଦ ପାଦ ଅନୁସାରେ ମାର୍ଗଦର୍ଶନ',
  'gs.hero.tag3': 'ବାସ୍ତବ ଜୀବନର ଉଦାହରଣ',
  'gs.what.title': 'OpenAlgo କଣ?',
  'gs.what.sub': 'ଏହାକୁ ଆପଣଙ୍କ ନିଜସ୍ୱ, ବ୍ୟକ୍ତିଗତ ଆଲଗୋ ଟ୍ରେଡିଂ ଇଞ୍ଜିନ୍ ଭାବେ ବିଚାର କରନ୍ତୁ, ଯାହାର ମାଲିକ ଆପଣ ନିଜେ ଏବଂ ଆପଣ ନିଜେ ଏହାକୁ ଚଲାନ୍ତି।',
  'gs.what.p1a': 'OpenAlgo ଏକ',
  'gs.what.p1strong': 'ମାଗଣା, ଓପନ୍-ସୋର୍ସ ଆଲଗୋ ଟ୍ରେଡିଂ ପ୍ଲାଟଫର୍ମ',
  'gs.what.p1b': 'ଭାରତୀୟ ବଜାର ପାଇଁ ତିଆରି। ଏହା ଏକ ୱେବ୍-ଆଧାରିତ ଆପ୍ଲିକେସନ୍ ଯାହା ଆପଣଙ୍କ ନିଜସ୍ୱ କମ୍ପ୍ୟୁଟର କିମ୍ବା ସର୍ଭରରେ ଚାଲେ। ଆପଣ ସମ୍ପୂର୍ଣ୍ଣ ସୋର୍ସ କୋଡ୍ ଡାଉନଲୋଡ୍ କରନ୍ତି, ଇନଷ୍ଟଲ୍ କରନ୍ତି, ଏବଂ ଆପଣଙ୍କର ନିଜସ୍ୱ ବ୍ୟକ୍ତିଗତ ଟ୍ରେଡିଂ ପ୍ଲାଟଫର୍ମ ହୋଇଯାଏ।',
  'gs.what.p2': 'ଏହା ଆପଣଙ୍କ ଟ୍ରେଡିଂ ଆଇଡିଆ (TradingView, Python, Amibroker, Excel ଭଳି ପ୍ଲାଟଫର୍ମରୁ) ଏବଂ ଆପଣଙ୍କ ବ୍ରୋକର ମଧ୍ୟରେ ଏକ ସେତୁ ଭାବେ କାର୍ଯ୍ୟ କରେ। ଆପଣ OpenAlgo କୁ ସିଗନାଲ୍ ପଠାନ୍ତି, ଏବଂ ଏହା ସ୍ୱୟଂଚାଳିତ ଭାବେ ଆପଣଙ୍କ ବ୍ରୋକର ଆକାଉଣ୍ଟରେ ଅର୍ଡର ପ୍ଲେସ୍ କରେ।',
  'gs.what.factsLabel': 'ମୁଖ୍ୟ ତଥ୍ୟ',
  'gs.what.fact1': 'ଏକକ-ୟୁଜର୍ ଆପ୍ଲିକେସନ୍: ଗୋଟିଏ ଇନଷ୍ଟାନ୍ସ, ଗୋଟିଏ ବ୍ରୋକର',
  'gs.what.fact2': 'କୌଣସି ବିଲ୍ଟ-ଇନ୍ ରଣନୀତି ନାହିଁ: ଆପଣ ନିଜର ଆଇଡିଆ ଆଣନ୍ତି',
  'gs.what.fact3': '33+ ଭାରତୀୟ ବ୍ରୋକର୍ ସପୋର୍ଟେଡ୍ (ଏବଂ ବଢ଼ୁଛି)',
  'gs.what.fact4': 'AI ଟୁଲ୍ ବ୍ୟବହାର କରି ଆପଣ ଆପଣଙ୍କ ରଣନୀତିକୁ ସହଜରେ କୋଡ୍ କରିପାରିବେ',
  'gs.what.fact5': '100% ମାଗଣା, 100% ଓପନ୍ ସୋର୍ସ (AGPL-3.0)',
