  'gs.remember.t3d': 'OpenAlgo ଭିତରେ Python ରଣନୀତି ହୋଷ୍ଟ କରିବା ସମୟରେ, ପୋଜିସନାଲ୍ ରଣନୀତି ପୁନଃଆରମ୍ଭରେ ବଞ୍ଚେ ନାହିଁ। ରଣନୀତି ଖୋଲା ପୋଜିସନ୍‌କୁ ଭୁଲିଯାଏ। ହୋଷ୍ଟେଡ୍ ରଣନୀତି ପାଇଁ ଇଣ୍ଟ୍ରାଡେକୁ ଲାଗି ରୁହନ୍ତୁ। ଏହା TradingView କିମ୍ବା Amibroker ଭଳି ବାହ୍ୟ ପ୍ଲାଟଫର୍ମ ପାଇଁ ଲାଗୁ ହୁଏ ନାହିଁ।',
  'gs.remember.t4t': 'ସେଟଅପ୍ ପରେ .env pepper key ପରିବର୍ତ୍ତନ କରନ୍ତୁ ନାହିଁ',
