  'sip.setup.s2Title': 'ଧାପ 2: Cloudflare ସେଟଅପ୍ କରନ୍ତୁ (ମାଗଣା)',
  'sip.setup.s2P1': 'ଏକ ମାଗଣା Cloudflare ଆକାଉଣ୍ଟ ପଞ୍ଜୀକରଣ କରନ୍ତୁ ଏବଂ ଆପଣଙ୍କ ଡୋମେନ ଯୋଡ଼ନ୍ତୁ। ଆପଣଙ୍କ ଡୋମେନ ରେଜିଷ୍ଟ୍ରାରର ନେମସର୍ଭରକୁ Cloudflareକୁ ପଏଣ୍ଟ କରନ୍ତୁ। ଏହା ଆପଣଙ୍କୁ DNS ମାନେଜମେଣ୍ଟ, ମାଗଣା SSL, ଏବଂ ସୁରକ୍ଷା ପ୍ରୋଟେକ୍ସନ୍ ଦେଇଥାଏ।',
  'sip.setup.s2Step1': 'ଏକ ମାଗଣା Cloudflare ଆକାଉଣ୍ଟ ତିଆରି କରନ୍ତୁ',
  'sip.setup.s2Step2': 'ଆପଣଙ୍କ ଡୋମେନ ଯୋଡ଼ନ୍ତୁ ଏବଂ ଆପଣଙ୍କ ରେଜିଷ୍ଟ୍ରାରରେ ନେମସର୍ଭର ଅପଡେଟ୍ କରନ୍ତୁ',
  'sip.setup.s2Step3': 'SSL/TLS ସେଟିଂସକୁ ଯାଆନ୍ତୁ ଏବଂ ମୋଡ୍‌କୁ Full (Strict) ସେଟ୍ କରନ୍ତୁ',
  'sip.setup.s2Step4': 'ଆପଣଙ୍କ ଡୋମେନକୁ ଆପଣଙ୍କ ସର୍ଭର IPକୁ ପଏଣ୍ଟ କରୁଥିବା ଏକ A ରେକର୍ଡ ତିଆରି କରନ୍ତୁ',
  'sip.setup.s2WhyTitle': 'କାହିଁକି Cloudflare?',
  'sip.setup.s2WhyDesc': 'ଏହା ବିନା, ଆପଣଙ୍କ ସର୍ଭର IP ସାର୍ବଜନୀନ ଭାବେ ଏକ୍ସପୋଜ୍ ହୁଏ। Cloudflare ଏକ ଢାଲ ଭାବେ କାର୍ଯ୍ୟ କରେ। 95% ବଟ୍ ଆକ୍ରମଣ ବ୍ଲକ୍ ହୁଏ। ଆପଣଙ୍କ ପ୍ରକୃତ ସର୍ଭର IP ଲୁକ୍କାୟିତ ରହେ।',
  'sip.setup.s3Title': 'ଧାପ 3: ଏକ ସର୍ଭର ଡିପ୍ଲଏ କରନ୍ତୁ',
  'sip.setup.s3P1': 'ଆପଣଙ୍କ ମନୋନୀତ ପ୍ରଦାତାଙ୍କ ସହିତ ଏକ ସର୍ଭର ସ୍ପିନ୍ ଅପ୍ କରନ୍ତୁ। Ubuntu (ଲାଟେଷ୍ଟ ଭର୍ସନ) ମନୋନୀତ କରନ୍ତୁ, ଏକ ମୁମ୍ବାଇ ଲୋକେସନ ବାଛନ୍ତୁ, ଏବଂ ଆପଣଙ୍କ ପ୍ଲାନ୍ ବାଛନ୍ତୁ।',
  'sip.setup.s3L1': 'OS',
  'sip.setup.s3V1': 'Ubuntu 24/25 (ଲାଟେଷ୍ଟ)',
  'sip.setup.s3L2': 'ଲୋକେସନ୍',
  'sip.setup.s3V2': 'ମୁମ୍ବାଇ (ଏକ୍ସଚେଞ୍ଜର ନିକଟତମ)',
  'sip.setup.s3L3': 'IP ଭର୍ସନ୍',
  'sip.setup.s3V3': 'IPv4 (ବ୍ରୋକରମାନଙ୍କ ପାଇଁ ବାଧ୍ୟତାମୂଳକ)',
  'sip.setup.s3P2': 'ଥରେ ଡିପ୍ଲଏ ହେଲେ, ଆପଣ ଏକ ପବ୍ଲିକ୍ IPv4 ଠିକଣା ଏବଂ ଏକ ରୁଟ୍ ପାସୱାର୍ଡ ପାଇବେ। Cloudflareକୁ ଫେରି ଯାଆନ୍ତୁ ଏବଂ ଏହି IP ସହିତ ଆପଣଙ୍କ A ରେକର୍ଡ ଅପଡେଟ୍ କରନ୍ତୁ।',
  'sip.setup.s4Title': 'ଧାପ 4: ବ୍ରୋକରରେ IP ହ୍ୱାଇଟଲିଷ୍ଟ କରନ୍ତୁ',
  'sip.setup.s4P1': 'ଆପଣଙ୍କ ବ୍ରୋକରର ଡେଭେଲପର ପୋର୍ଟାଲକୁ ଯାଆନ୍ତୁ ଏବଂ ଆପଣଙ୍କ API ଆପ୍ ତିଆରି କିମ୍ବା ଏଡିଟ୍ କରନ୍ତୁ। ଆପଣଙ୍କ ସର୍ଭରର ଷ୍ଟାଟିକ୍ IPକୁ ପ୍ରାଇମେରୀ IP ଭାବେ ସଂଲଗ୍ନ କରନ୍ତୁ।',
  'sip.setup.s4NoteTitle': 'ପ୍ରତ୍ୟେକ ବ୍ରୋକର ଭିନ୍ନ:',
  'sip.setup.s4NoteDesc': 'କେତେକ ବ୍ରୋକରର ସେମାନଙ୍କ ଡେଭେଲପର ପୋର୍ଟାଲରେ ଏକ ଅଲଗା IP ହ୍ୱାଇଟଲିଷ୍ଟିଂ ସେକ୍ସନ୍ ଥାଏ। ଅନ୍ୟମାନେ API ଆପ୍ ତିଆରି ସମୟରେ ହିଁ IP ସଂଲଗ୍ନ ଆବଶ୍ୟକ କରନ୍ତି। ସଠିକ୍ ପଦକ୍ଷେପ ପାଇଁ ଆପଣଙ୍କ ନିର୍ଦ୍ଦିଷ୍ଟ ବ୍ରୋକରର ଡେଭେଲପର ଡକ୍ୟୁମେଣ୍ଟେସନ୍ ଯାଞ୍ଚ କରନ୍ତୁ।',
  'sip.setup.s5Title': 'ଧାପ 5: OpenAlgo ଇନଷ୍ଟଲ୍ କରନ୍ତୁ',
  'sip.setup.s5P1': 'ଆପଣଙ୍କ ସର୍ଭରକୁ SSH କରନ୍ତୁ ଏବଂ ଇନଷ୍ଟଲେସନ୍ ସ୍କ୍ରିପ୍ଟ ରନ୍ କରନ୍ତୁ:',
  'sip.setup.s5P2': 'ସ୍କ୍ରିପ୍ଟ ଆପଣଙ୍କ ଡୋମେନ, ବ୍ରୋକର ନାମ, API କି, ଏବଂ API ସିକ୍ରେଟ୍ ପଚାରିବ। ଏହା ବାକି ସବୁକିଛି ସ୍ୱୟଂଚାଳିତ ଭାବେ ପରିଚାଳନା କରେ:',
  'sip.setup.s5i1': 'ଫାୟାରୱାଲ୍ କନଫିଗରେସନ୍',
  'sip.setup.s5i2': 'Nginx ରିଭର୍ସ ପ୍ରୋକ୍ସି',
  'sip.setup.s5i3': "Let's Encrypt ମାଧ୍ୟମରେ ମାଗଣା SSL",
  'sip.setup.s5i4': 'Python ଭର୍ଚୁଆଲ୍ ଏନଭାଏରନମେଣ୍ଟ',
  'sip.setup.s5i5': 'ସମସ୍ତ 177+ ଲାଇବ୍ରେରୀ',
  'sip.setup.s5i6': 'Systemd ସର୍ଭିସ୍ (24/7 ଅପଟାଇମ୍)',
  'sip.setup.s5MultiTitle': 'ଏକାଧିକ ଆକାଉଣ୍ଟ?',
  'sip.setup.s5MultiA': 'ବ୍ୟବହାର କରନ୍ତୁ',
  'sip.setup.s5MultiB': 'ଏକ ସର୍ଭରରେ ଏକାଧିକ OpenAlgo ଇନଷ୍ଟାନ୍ସ ଚଲାଇବା ପାଇଁ ବଦଳରେ। ନିଶ୍ଚିତ କରନ୍ତୁ ସମସ୍ତ ଆକାଉଣ୍ଟ SEBI ଗାଇଡଲାଇନ୍ ଅନୁସାରେ ଆପଣ କିମ୍ବା ଆପଣଙ୍କ ପରିବାରର ଅଟେ।',
  'sip.setup.s6Title': 'ଧାପ 6: ଲଗଇନ୍ & ଯାଞ୍ଚ କରନ୍ତୁ',
  'sip.setup.s6P1': 'ଏକ ବ୍ରାଉଜରରେ ଆପଣଙ୍କ ଡୋମେନ (ଉଦାହରଣ ସ୍ୱରୂପ, myalgo.yourdomain.in) ଖୋଲନ୍ତୁ। ତୁରନ୍ତ ଆପଣଙ୍କ ଆକାଉଣ୍ଟ ପଞ୍ଜୀକରଣ କରନ୍ତୁ (ପ୍ରଥମ ୟୁଜର୍ ଆଡମିନ୍ ହୁଅନ୍ତି)। ଆପଣଙ୍କ ବ୍ରୋକର ସଂଯୋଗ କରନ୍ତୁ ଏବଂ ମାଷ୍ଟର ଚୁକ୍ତି ଡାଉନଲୋଡ୍ ଯାଞ୍ଚ କରନ୍ତୁ।',
  'sip.arch.title': 'ସର୍ଭର ଆର୍କିଟେକଚର',
  'sip.arch.sub': 'କଣ ଇନଷ୍ଟଲ୍ ହୁଏ ଏବଂ ଅଂଶଗୁଡ଼ିକ କିପରି ଏକାଠି ଫିଟ୍ ହୁଅନ୍ତି।',
  'sip.arch.f1L': 'ଆପଣଙ୍କ ବ୍ରାଉଜର୍',
