  'sip.arch.c1T': 'UFW ଫାୟାରୱାଲ୍',
  'sip.arch.c1D': 'କେବଳ ପୋର୍ଟ 22 (SSH), 80 (HTTP), ଏବଂ 443 (HTTPS) ଖୋଲା ଅଛି। ବାକି ସବୁକିଛି ବ୍ଲକ୍ ହୋଇଛି।',
  'sip.arch.c2D': 'ରିଭର୍ସ ପ୍ରୋକ୍ସି ଯାହା ବ୍ରାଉଜର ରିକ୍ୱେଷ୍ଟକୁ OpenAlgoକୁ ରାଉଟ୍ କରେ। SSL ଟର୍ମିନେସନ୍ ପରିଚାଳନା କରେ।',
  'sip.arch.c3D': 'ମାଗଣା SSL ସାର୍ଟିଫିକେଟ୍। ସ୍ୱୟଂଚାଳିତ ଭାବେ ରିନିୱ୍ ହୁଏ। ଏଣ୍ଡ ଟୁ ଏଣ୍ଡ HTTPS ଏନକ୍ରିପସନ୍ ପ୍ରଦାନ କରେ।',
  'sip.arch.c4T': 'Systemd ସର୍ଭିସ୍',
