  'sip.arch.sigTitle': 'ସିଗନାଲ୍ ରାଉଟିଂ: ଅର୍ଡର କେଉଁଠାରୁ ଆସେ?',
  'sip.arch.sigDesc': 'ଯଦିଓ ଆପଣଙ୍କ ଷ୍ଟ୍ରାଟେଜି ଘରୁ ଚାଲେ (Amibroker, Python, TradingView), ସିଗନାଲ୍ ଆପଣଙ୍କ ସର୍ଭରକୁ ପଠାଯାଏ। ସର୍ଭରରେ OpenAlgo ସେଗୁଡ଼ିକୁ ପ୍ରକ୍ରିୟାକରଣ କରେ ଏବଂ ଅର୍ଡର ପ୍ଲେସ୍ କରେ। ବ୍ରୋକର କେବଳ ଆପଣଙ୍କ ସର୍ଭରର ଷ୍ଟାଟିକ୍ IP ଦେଖେ, ଆପଣଙ୍କ ଘର IP ନୁହେଁ।',
