  'sip.up.sub': 'ସର୍ଭରରେ ଆପଣଙ୍କ OpenAlgo ଇନଷ୍ଟାନ୍ସକୁ କିପରି ଅପ୍-ଟୁ-ଡେଟ୍ ରଖିବେ।',
  'sip.up.stepsTitle': 'ଅପଗ୍ରେଡ୍ ପଦକ୍ଷେପ',
  'sip.up.noteTitle': 'ଟିପ୍ପଣୀ:',
  'sip.up.noteDesc': 'ଅପଗ୍ରେଡ୍ କୋର OpenAlgo ଫାଇଲଗୁଡ଼ିକୁ ଓଭରରାଇଟ୍ କରେ। strategies ଫୋଲଡର ଭିତରେ ଥିବା ଆପଣଙ୍କ କଷ୍ଟମ୍ ଷ୍ଟ୍ରାଟେଜିଗୁଡ଼ିକ ସୁରକ୍ଷିତ ରହେ। ଯଦି ଆପଣଙ୍କ .env ଫାଇଲ୍ ବଦଳି ଯାଏ, ତେବେ ଆପଣଙ୍କ ବ୍ୟାକଅପ୍‌ରୁ API key, API secret, ଏବଂ redirect URL ପୁନଃସ୍ଥାପନ କରନ୍ତୁ।',
  'sip.up.cmdTitle': 'ଉପଯୋଗୀ ସର୍ଭର କମାଣ୍ଡଗୁଡ଼ିକ',
  'sip.up.cmd1': 'OpenAlgo ଚାଲୁଛି କି ନାହିଁ ଯାଞ୍ଚ କରନ୍ତୁ',
